fn putmask(a: Vec<f32>, mask: Vec<bool>, values: Vec<f32>) -> Vec<f32> {
    // Create result vector with same capacity as input
    let mut result = Vec::with_capacity(a.len());
    
    // Get the length of values for modulo operation
    let values_len = values.len();
    
    // Iterate through all indices
    for i in 0..a.len() {
        if mask[i] {
            // Use replacement value at index i modulo values_len
            result.push(values[i % values_len]);
        } else {
            // Use original value from input array
            result.push(a[i]);
        }
    }
    
    result
}